bell_pavilion.source:
export const envelope = [19, 18, 19];

export default function build(api) {
  // Helper to strip existing block states
  function getBase(blockStr) {
    if (!blockStr) return "minecraft:stone";
    const idx = blockStr.indexOf("[");
    return idx === -1 ? blockStr : blockStr.substring(0, idx);
  }

  // Safe theme extraction with thematic Japanese timber temple fallbacks
  const woodPlanks = api.theme?.wood?.planks || "minecraft:dark_oak_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:dark_oak_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_dark_oak_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:dark_oak_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:dark_oak_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:dark_oak_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:dark_oak_trapdoor";

  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:mossy_stone_bricks";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const roofSolid = api.theme?.roof?.solid || "minecraft:deepslate_tiles";
  const roofStairs = api.theme?.roof?.stairs || "minecraft:deepslate_tile_stairs";
  const roofSlab = api.theme?.roof?.slab || "minecraft:deepslate_tile_slab";

  // Block builders
  function stair(baseStr, facing, half = "bottom", shape = null) {
    const base = getBase(baseStr);
    let state = `facing=${facing},half=${half}`;
    if (shape) state += `,shape=${shape}`;
    return `${base}[${state}]`;
  }

  function slab(baseStr, type = "bottom") {
    const base = getBase(baseStr);
    return `${base}[type=${type}]`;
  }

  function log(baseStr, axis = "y") {
    const base = getBase(baseStr);
    return `${base}[axis=${axis}]`;
  }

  function trapdoor(baseStr, facing = "north", half = "bottom", open = false) {
    const base = getBase(baseStr);
    return `${base}[facing=${facing},half=${half},open=${open}]`;
  }

  function fence(baseStr) {
    return getBase(baseStr);
  }

  // --- 1. GROUND CONFORMANCE & FOUNDATION PLINTH (Rule 6) ---
  for (let x = 0; x < 19; x++) {
    for (let z = 0; z < 19; z++) {
      const isPlinth = x >= 3 && x <= 15 && z >= 3 && z <= 15;
      const isSteps = x >= 8 && x <= 10 && z >= 1 && z <= 2;
      const isApron = x >= 2 && x <= 16 && z >= 2 && z <= 16 && !isPlinth && !isSteps;

      const groundY = Math.round(api.heightAt(x, z));

      if (isPlinth) {
        const minY = Math.min(0, groundY);
        for (let y = minY; y <= 0; y++) {
          const mat = api.random() < 0.2 ? stoneAccent : stonePrimary;
          api.set(x, y, z, mat);
        }
      } else if (isSteps) {
        const minY = Math.min(0, groundY);
        for (let y = minY; y <= 0; y++) {
          api.set(x, y, z, stonePrimary);
        }
      } else if (isApron && groundY < 0) {
        for (let y = groundY; y <= 0; y++) {
          api.set(x, y, z, stonePrimary);
        }
      }
    }
  }

  // --- 2. STEPPED STONE BASE (Kidan) ---
  // Level 0: Outer perimeter of main plinth (x: 3..15, z: 3..15)
  for (let x = 3; x <= 15; x++) {
    for (let z = 3; z <= 15; z++) {
      if (z === 3 && (x < 8 || x > 10)) {
        api.set(x, 0, z, stair(stoneStairs, "north"));
      } else if (z === 15) {
        api.set(x, 0, z, stair(stoneStairs, "south"));
      } else if (x === 3) {
        api.set(x, 0, z, stair(stoneStairs, "west"));
      } else if (x === 15) {
        api.set(x, 0, z, stair(stoneStairs, "east"));
      } else {
        api.set(x, 0, z, (x + z) % 5 === 0 ? stoneAccent : stonePrimary);
      }
    }
  }
  // North entrance steps at y = 0
  for (let x = 8; x <= 10; x++) {
    api.set(x, 0, 1, stair(stoneStairs, "north"));
    api.set(x, 0, 2, stonePrimary);
  }

  // Level 1: Middle stone tier (x: 4..14, z: 4..14)
  for (let x = 4; x <= 14; x++) {
    for (let z = 4; z <= 14; z++) {
      if (z === 4 && (x < 8 || x > 10)) {
        api.set(x, 1, z, stair(stoneStairs, "north"));
      } else if (z === 14) {
        api.set(x, 1, z, stair(stoneStairs, "south"));
      } else if (x === 4) {
        api.set(x, 1, z, stair(stoneStairs, "west"));
      } else if (x === 14) {
        api.set(x, 1, z, stair(stoneStairs, "east"));
      } else {
        api.set(x, 1, z, stonePrimary);
      }
    }
  }
  // North entrance steps at y = 1
  for (let x = 8; x <= 10; x++) {
    api.set(x, 1, 2, stair(stoneStairs, "north"));
    api.set(x, 1, 3, stonePrimary);
  }

  // Standing stone lanterns at entrance (x=6, z=2 and x=12, z=2)
  for (const lx of [6, 12]) {
    api.set(lx, 1, 2, stoneWall);
    api.set(lx, 2, 2, "minecraft:lantern[hanging=false]");
    api.set(lx, 3, 2, slab(stoneSlab, "bottom"));
  }

  // --- 3. TIMBER PLATFORM & FLOORING (y = 2) ---
  for (let x = 5; x <= 13; x++) {
    for (let z = 5; z <= 13; z++) {
      const isPerimeter = x === 5 || x === 13 || z === 5 || z === 13;
      if (isPerimeter) {
        if (z === 5 && x >= 8 && x <= 10) {
          api.set(x, 2, z, stair(woodStairs, "north"));
        } else {
          api.set(x, 2, z, log(woodLog, x === 5 || x === 13 ? "z" : "x"));
        }
      } else {
        // Polished parquet floor
        const axis = Math.floor(x / 2) % 2 === 0 ? "x" : "z";
        api.set(x, 2, z, log(woodStripped, axis));
      }
    }
  }

  // Column plinth stones (Hashira-ishi) at y = 2
  const pillars = [
    [6, 6],
    [12, 6],
    [6, 12],
    [12, 12],
  ];
  for (const [px, pz] of pillars) {
    api.set(px, 2, pz, "minecraft:chiseled_stone_bricks");
  }

  // --- 4. CORNER PILLARS & BALUSTRADE (y = 3..8) ---
  // Massive cedar corner posts
  for (const [px, pz] of pillars) {
    for (let y = 3; y <= 8; y++) {
      api.set(px, y, pz, log(woodLog, "y"));
    }
  }

  // Flared pillar bases at y = 3
  api.set(5, 3, 6, stair(woodStairs, "east"));
  api.set(7, 3, 6, stair(woodStairs, "west"));
  api.set(6, 3, 7, stair(woodStairs, "north"));
  api.set(11, 3, 6, stair(woodStairs, "east"));
  api.set(13, 3, 6, stair(woodStairs, "west"));
  api.set(12, 3, 7, stair(woodStairs, "north"));
  api.set(5, 3, 12, stair(woodStairs, "east"));
  api.set(7, 3, 12, stair(woodStairs, "west"));
  api.set(6, 3, 11, stair(woodStairs, "south"));
  api.set(11, 3, 12, stair(woodStairs, "east"));
  api.set(13, 3, 12, stair(woodStairs, "west"));
  api.set(12, 3, 11, stair(woodStairs, "south"));

  // Low perimeter railing (Kouran) at y = 3
  for (let z = 6; z <= 12; z++) {
    api.set(5, 3, z, fence(woodFence));
    api.set(13, 3, z, fence(woodFence));
  }
  for (let x = 6; x <= 12; x++) {
    api.set(x, 3, 13, fence(woodFence));
  }
  api.set(5, 3, 5, fence(woodFence));
  api.set(6, 3, 5, fence(woodFence));
  api.set(7, 3, 5, fence(woodFence));
  api.set(11, 3, 5, fence(woodFence));
  api.set(12, 3, 5, fence(woodFence));
  api.set(13, 3, 5, fence(woodFence));

  // Mid-height Tie-Beams (Nuki) at y = 5
  for (let x = 7; x <= 11; x++) {
    api.set(x, 5, 6, log(woodStripped, "x"));
    api.set(x, 5, 12, log(woodStripped, "x"));
  }
  for (let z = 7; z <= 11; z++) {
    api.set(6, 5, z, log(woodStripped, "z"));
    api.set(12, 5, z, log(woodStripped, "z"));
  }
  // Decorative brackets under mid-beams at y = 4
  api.set(7, 4, 6, stair(woodStairs, "west", "top"));
  api.set(11, 4, 6, stair(woodStairs, "east", "top"));
  api.set(7, 4, 12, stair(woodStairs, "west", "top"));
  api.set(11, 4, 12, stair(woodStairs, "east", "top"));
  api.set(6, 4, 7, stair(woodStairs, "north", "top"));
  api.set(6, 4, 11, stair(woodStairs, "south", "top"));
  api.set(12, 4, 7, stair(woodStairs, "north", "top"));
  api.set(12, 4, 11, stair(woodStairs, "south", "top"));

  // --- 5. UPPER BEAMS & CENTRAL SUSPENSION FRAME (y = 8) ---
  // Perimeter header beams with extended carved kibana ends (x: 5..13, z: 5..13)
  for (let x = 5; x <= 13; x++) {
    api.set(x, 8, 6, log(woodLog, "x"));
    api.set(x, 8, 12, log(woodLog, "x"));
  }
  for (let z = 5; z <= 13; z++) {
    api.set(6, 8, z, log(woodLog, "z"));
    api.set(12, 8, z, log(woodLog, "z"));
  }

  // Central cruciform bell-bearing girder at y = 8
  for (let x = 7; x <= 11; x++) {
    api.set(x, 8, 9, log(woodLog, "x"));
  }
  for (let z = 7; z <= 11; z++) {
    api.set(9, 8, z, log(woodLog, "z"));
  }

  // Support brackets under beam overhangs at y = 7
  api.set(5, 7, 6, stair(woodStairs, "east", "top"));
  api.set(13, 7, 6, stair(woodStairs, "west", "top"));
  api.set(5, 7, 12, stair(woodStairs, "east", "top"));
  api.set(13, 7, 12, stair(woodStairs, "west", "top"));
  api.set(6, 7, 5, stair(woodStairs, "south", "top"));
  api.set(6, 7, 13, stair(woodStairs, "north", "top"));
  api.set(12, 7, 5, stair(woodStairs, "south", "top"));
  api.set(12, 7, 13, stair(woodStairs, "north", "top"));

  // --- 6. THE GREAT BRONZE TEMPLE BELL (Bonshō) ---
  // Center is at (9, y, 9)
  // Ryūzu (Dragon Crown / Hanging Eye) at y = 7
  api.set(9, 7, 9, "minecraft:chain[axis=y]");
  api.set(9, 7, 8, "minecraft:exposed_cut_copper_stairs[facing=south,half=top]");
  api.set(9, 7, 10, "minecraft:exposed_cut_copper_stairs[facing=north,half=top]");

  // Kasagata (Upper Rounded Bell Dome) at y = 6
  api.set(9, 6, 9, "minecraft:weathered_cut_copper");
  api.set(9, 6, 8, "minecraft:weathered_cut_copper_stairs[facing=north,half=bottom]");
  api.set(9, 6, 10, "minecraft:weathered_cut_copper_stairs[facing=south,half=bottom]");
  api.set(8, 6, 9, "minecraft:weathered_cut_copper_stairs[facing=west,half=bottom]");
  api.set(10, 6, 9, "minecraft:weathered_cut_copper_stairs[facing=east,half=bottom]");
  api.set(8, 6, 8, "minecraft:weathered_cut_copper_slab[type=bottom]");
  api.set(10, 6, 8, "minecraft:weathered_cut_copper_slab[type=bottom]");
  api.set(8, 6, 10, "minecraft:weathered_cut_copper_slab[type=bottom]");
  api.set(10, 6, 10, "minecraft:weathered_cut_copper_slab[type=bottom]");

  // Nyū (Upper Barrel with Lotus Boss Relieves) at y = 5
  api.set(9, 5, 9, "minecraft:weathered_cut_copper");
  api.set(9, 5, 8, "minecraft:exposed_cut_copper");
  api.set(9, 5, 10, "minecraft:exposed_cut_copper");
  api.set(8, 5, 9, "minecraft:exposed_cut_copper");
  api.set(10, 5, 9, "minecraft:exposed_cut_copper");
  api.set(8, 5, 8, "minecraft:weathered_cut_copper");
  api.set(10, 5, 8, "minecraft:weathered_cut_copper");
  api.set(8, 5, 10, "minecraft:weathered_cut_copper");
  api.set(10, 5, 10, "minecraft:weathered_cut_copper");

  // Middle Barrel & Tsukiza (Striking Medallion) at y = 4
  api.set(9, 4, 9, "minecraft:weathered_cut_copper");
  api.set(9, 4, 8, "minecraft:oxidized_cut_copper");
  api.set(9, 4, 10, "minecraft:oxidized_cut_copper");
  api.set(8, 4, 9, "minecraft:oxidized_cut_copper");
  api.set(10, 4, 9, "minecraft:chiseled_copper"); // Medallion facing the striker!
  api.set(8, 4, 8, "minecraft:weathered_cut_copper");
  api.set(10, 4, 8, "minecraft:weathered_cut_copper");
  api.set(8, 4, 10, "minecraft:weathered_cut_copper");
  api.set(10, 4, 10, "minecraft:weathered_cut_copper");

  // Koma-no-tsume (Flared Rim & Resonant Mouth) at y = 3
  api.set(9, 3, 9, "minecraft:bell[attachment=ceiling,facing=north]");
  api.set(9, 3, 8, "minecraft:weathered_cut_copper_stairs[facing=south,half=top]");
  api.set(9, 3, 10, "minecraft:weathered_cut_copper_stairs[facing=north,half=top]");
  api.set(8, 3, 9, "minecraft:weathered_cut_copper_stairs[facing=east,half=top]");
  api.set(10, 3, 9, "minecraft:weathered_cut_copper_stairs[facing=west,half=top]");
  api.set(8, 3, 8, "minecraft:weathered_cut_copper_slab[type=top]");
  api.set(10, 3, 8, "minecraft:weathered_cut_copper_slab[type=top]");
  api.set(8, 3, 10, "minecraft:weathered_cut_copper_slab[type=top]");
  api.set(10, 3, 10, "minecraft:weathered_cut_copper_slab[type=top]");

  // --- 7. SUSPENDED LOG STRIKER (Shumoku) ---
  // Horizontal striker log hung parallel at x = 11, y = 4, aiming at the bell's striking point
  api.set(11, 4, 7, "minecraft:dark_oak_fence_gate[facing=north,in_wall=false,open=false]");
  api.set(11, 4, 8, "minecraft:stripped_dark_oak_log[axis=z]");
  api.set(11, 4, 9, "minecraft:stripped_dark_oak_log[axis=z]");
  api.set(11, 4, 10, "minecraft:stripped_dark_oak_log[axis=z]");

  // Suspension ropes (chains) from ceiling beam at y = 8 down to striker at y = 4
  for (let y = 5; y <= 7; y++) {
    api.set(11, y, 8, "minecraft:chain[axis=y]");
    api.set(11, y, 10, "minecraft:chain[axis=y]");
  }
  // Ringing lanyard / pull rope hanging down from the rear of the striker
  api.set(11, 3, 10, "minecraft:chain[axis=y]");
  api.set(11, 3, 9, trapdoor(woodTrapdoor, "east", "top"));

  // --- 8. BRACKET COMPLEXES (Dougong / Tokyō) (y = 9..10) ---
  // Bracket blocks and arms at y = 9
  for (const [px, pz] of pillars) {
    api.set(px, 9, pz, woodPlanks);
    api.set(px - 1, 9, pz, stair(woodStairs, "west", "top"));
    api.set(px + 1, 9, pz, stair(woodStairs, "east", "top"));
    api.set(px, 9, pz - 1, stair(woodStairs, "north", "top"));
    api.set(px, 9, pz + 1, stair(woodStairs, "south", "top"));
  }
  // Mid-span bracket blocks at y = 9
  const midBrackets = [
    [9, 6],
    [9, 12],
    [6, 9],
    [12, 9],
  ];
  for (const [mx, mz] of midBrackets) {
    api.set(mx, 9, mz, woodPlanks);
    if (mx === 9) {
      api.set(mx - 1, 9, mz, stair(woodStairs, "west", "top"));
      api.set(mx + 1, 9, mz, stair(woodStairs, "east", "top"));
      api.set(mx, 9, mz === 6 ? 5 : 13, stair(woodStairs, mz === 6 ? "north" : "south", "top"));
    } else {
      api.set(mx, 9, mz - 1, stair(woodStairs, "north", "top"));
      api.set(mx, 9, mz + 1, stair(woodStairs, "south", "top"));
      api.set(mx === 6 ? 5 : 13, 9, mz, stair(woodStairs, mx === 6 ? "west" : "east", "top"));
    }
  }

  // Hanging copper lanterns from the 4 bracket corners
  const lanternCorners = [
    [5, 5],
    [13, 5],
    [5, 13],
    [13, 13],
  ];
  for (const [cx, cz] of lanternCorners) {
    api.set(cx, 9, cz, woodPlanks);
    api.set(cx, 8, cz, "minecraft:chain[axis=y]");
    api.set(cx, 7, cz, "minecraft:chain[axis=y]");
    api.set(cx, 6, cz, "minecraft:lantern[hanging=true]");
  }

  // Outer purlin ring beam (Keta) at y = 10 (x: 4..14, z: 4..14)
  for (let x = 4; x <= 14; x++) {
    api.set(x, 10, 4, log(woodLog, "x"));
    api.set(x, 10, 14, log(woodLog, "x"));
  }
  for (let z = 4; z <= 14; z++) {
    api.set(4, 10, z, log(woodLog, "z"));
    api.set(14, 10, z, log(woodLog, "z"));
  }
  // Cantilever arms under purlin ring at y = 10
  for (let x = 5; x <= 13; x += 2) {
    api.set(x, 10, 5, woodPlanks);
    api.set(x, 10, 13, woodPlanks);
  }
  for (let z = 5; z <= 13; z += 2) {
    api.set(5, 10, z, woodPlanks);
    api.set(13, 10, z, woodPlanks);
  }

  // Exposed under-eave rafters (Taruki) at y = 11 (x: 2..16, z: 2..16)
  for (let x = 3; x <= 15; x++) {
    api.set(x, 11, 3, stair(woodStairs, "south", "top"));
    api.set(x, 11, 15, stair(woodStairs, "north", "top"));
  }
  for (let z = 3; z <= 15; z++) {
    api.set(3, 11, z, stair(woodStairs, "east", "top"));
    api.set(15, 11, z, stair(woodStairs, "west", "top"));
  }

  // --- 9. SWEEPING HIPPED TILE ROOF (Irimoya-yane) (y = 12..17) ---
  // Tier 0: Flared Outer Eaves (y = 12, with swept corners at y = 13)
  // Boundary x in 1..17, z in 1..17
  for (let x = 1; x <= 17; x++) {
    for (let z = 1; z <= 17; z++) {
      const isOuterEdge = x === 1 || x === 17 || z === 1 || z === 17;
      if (!isOuterEdge) continue;

      const isExtremeCorner =
        (x <= 2 && z <= 2) ||
        (x >= 16 && z <= 2) ||
        (x <= 2 && z >= 16) ||
        (x >= 16 && z >= 16);

      if (isExtremeCorner) {
        // Dramatic flared corner tip (Nokisaki-sori)
        api.set(x, 12, z, roofSolid);
        if (
          (x === 1 && z === 1) ||
          (x === 17 && z === 1) ||
          (x === 1 && z === 17) ||
          (x === 17 && z === 17)
        ) {
          api.set(x, 13, z, slab(roofSlab, "bottom"));
        } else {
          api.set(x, 13, z, slab(roofSlab, "bottom"));
        }
      } else {
        // Straight eave edges
        if (z === 1) api.set(x, 12, z, stair(roofStairs, "north"));
        else if (z === 17) api.set(x, 12, z, stair(roofStairs, "south"));
        else if (x === 1) api.set(x, 12, z, stair(roofStairs, "west"));
        else if (x === 17) api.set(x, 12, z, stair(roofStairs, "east"));
      }
    }
  }

  // Tier 1: Second Eave Ring (y = 13, x: 2..16, z: 2..16)
  for (let x = 2; x <= 16; x++) {
    for (let z = 2; z <= 16; z++) {
      const isEdge = x === 2 || x === 16 || z === 2 || z === 16;
      if (!isEdge) continue;

      const isCorner =
        (x <= 3 && z <= 3) ||
        (x >= 15 && z <= 3) ||
        (x <= 3 && z >= 15) ||
        (x >= 15 && z >= 15);

      if (isCorner) {
        api.set(x, 13, z, roofSolid);
      } else {
        if (z === 2) api.set(x, 13, z, stair(roofStairs, "north"));
        else if (z === 16) api.set(x, 13, z, stair(roofStairs, "south"));
        else if (x === 2) api.set(x, 13, z, stair(roofStairs, "west"));
        else if (x === 16) api.set(x, 13, z, stair(roofStairs, "east"));
      }
    }
  }

  // Tier 2: Mid Slope (y = 14, x: 4..14, z: 4..14)
  for (let x = 4; x <= 14; x++) {
    for (let z = 4; z <= 14; z++) {
      const isEdge = x === 4 || x === 14 || z === 4 || z === 14;
      if (isEdge) {
        if (z === 4 && x > 4 && x < 14) api.set(x, 14, z, stair(roofStairs, "north"));
        else if (z === 14 && x > 4 && x < 14) api.set(x, 14, z, stair(roofStairs, "south"));
        else if (x === 4 && z > 4 && z < 14) api.set(x, 14, z, stair(roofStairs, "west"));
        else if (x === 14 && z > 4 && z < 14) api.set(x, 14, z, stair(roofStairs, "east"));
        else api.set(x, 14, z, roofSolid);
      } else {
        api.set(x, 13, z, roofSolid); // Solid backing
      }
    }
  }

  // Tier 3: Upper Slope (y = 15, x: 6..12, z: 6..12)
  for (let x = 6; x <= 12; x++) {
    for (let z = 6; z <= 12; z++) {
      const isEdge = x === 6 || x === 12 || z === 6 || z === 12;
      if (isEdge) {
        if (z === 6 && x > 6 && x < 12) api.set(x, 15, z, stair(roofStairs, "north"));
        else if (z === 12 && x > 6 && x < 12) api.set(x, 15, z, stair(roofStairs, "south"));
        else if (x === 6 && z > 6 && z < 12) api.set(x, 15, z, stair(roofStairs, "west"));
        else if (x === 12 && z > 6 && z < 12) api.set(x, 15, z, stair(roofStairs, "east"));
        else api.set(x, 15, z, roofSolid);
      } else {
        api.set(x, 14, z, roofSolid);
      }
    }
  }

  // Tier 4: Crown & Main Ridge (Mune) at y = 16..17
  // y = 16: Ridge base and apex slopes
  for (let x = 7; x <= 11; x++) {
    api.set(x, 16, 7, stair(roofStairs, "north"));
    api.set(x, 16, 8, roofSolid);
    api.set(x, 16, 9, roofSolid);
    api.set(x, 16, 10, roofSolid);
    api.set(x, 16, 11, stair(roofStairs, "south"));
  }
  api.set(7, 16, 8, stair(roofStairs, "west"));
  api.set(7, 16, 9, stair(roofStairs, "west"));
  api.set(7, 16, 10, stair(roofStairs, "west"));
  api.set(11, 16, 8, stair(roofStairs, "east"));
  api.set(11, 16, 9, stair(roofStairs, "east"));
  api.set(11, 16, 10, stair(roofStairs, "east"));

  // y = 17: Ridge Crest (Mune) & Onigawara End Finials
  for (let x = 8; x <= 10; x++) {
    api.set(x, 17, 9, slab(roofSlab, "bottom"));
  }
  // West onigawara finial
  api.set(7, 17, 9, stair(roofStairs, "east", "top"));
  // East onigawara finial
  api.set(11, 17, 9, stair(roofStairs, "west", "top"));

  return {
    name: "Great Temple Bell Pavilion (Shōrō)",
    seatY: 0,
    anchors: {
      front: [9, 0, 0],
      door: [9, 2, 5],
      bell: [9, 4, 9],
    },
  };
}
